    "content": "9月11日晚间，证监会公布四份行政处罚决定书。四名当事人均被认定存在编造、传播虚假信息的违法行为，且均没有违法所得。其中，宗建树被采取5年市场禁入措施，马星瑞被处以30万元罚款，卢润凯、陈广华分别被处以20万元罚款。 编造信息并在微信群发 布 2025年12月16日，证券从业人员宗建树编造与税率调整有关的信息，并在微信群内发布。经查，上述信息为虚假信息。 处罚决定书显示，宗建树作为证券从业人员，未履行必要的注意义务，在未考量、核实相关信息真实性的情况下编造、传播虚假信息，导致相关信息在互联网平台广泛传播，扰乱证券市…"
