    "content": "新华社纽约9月11日电 纽约股市三大股指11日上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨509.19点，收于52573.29点，涨幅为0.98%；标准普尔500种股票指数上涨65.28点，收于7656.98点，涨幅为0.86%；纳斯达克综合指数上涨251.31点，收于26333.04点，涨幅为0.96%。 板块方面，标普500指数十一大板块九涨二跌。通信服务板块和非必需消费品板块分别以1.35%和1.13%的涨幅领涨，公用事业板块和医疗板块分别下跌0.34%和0.14%。"
