    "author": "尚绪谦",
    "description": "新华社联合国9月11日电 中国常驻联合国代表团临时代办孙磊11日在安理会表决苏丹制裁问题决议草案后作解释性发言，警告不要随意扩大制裁范围。 孙磊说，考虑到安理会成员间分歧明显，执笔国美国提出对苏丹达尔富尔地区采取的制裁措施授权进行一个月的技术性延期，使大家有更充分时间讨论，中方对此不持异议，在表决中投了赞成票。中方一贯主张要确保决议草案的客观性、公正性和包容性，避免强推争议明显的案文。 他说，中方对苏丹严峻人道局势深感痛心，一直呼吁冲突…",
    "content": "新华社联合国9月11日电 中国常驻联合国代表团临时代办孙磊11日在安理会表决苏丹制裁问题决议草案后作解释性发言，警告不要随意扩大制裁范围。 孙磊说，考虑到安理会成员间分歧明显，执笔国美国提出对苏丹达尔富尔地区采取的制裁措施授权进行一个月的技术性延期，使大家有更充分时间讨论，中方对此不持异议，在表决中投了赞成票。中方一贯主张要确保决议草案的客观性、公正性和包容性，避免强推争议明显的案文。 他说，中方对苏丹严峻人道局势深感痛心，一直呼吁冲突各方立即停火止战，遵守国际人道法义务，停止外部军事干涉。同时，中方多次强调制裁是…"
