    "pub_date": "2026-09-12 02:43:41",
    "author": "田睿",
    "description": "新华社加拉加斯9月11日电（记者田睿）委内瑞拉执政党统一社会主义党11日在社交媒体发布公告说，遭美国关押的马杜罗总统夫妇的辩护团队以健康理由申请暂时释放第一夫人西莉亚·弗洛雷斯。 根据该公告，辩护团队向美国纽约一家法院提交了申请，请求基于“危急的医疗状况”、宪法原则及安全保证，批准第一夫人暂时获释。 公告显示，弗洛雷斯正经历“心脏及身体健康状况的严重恶化”，症状包括严重心律失常、心动过速以及符合冠状动脉缺血特征的发作症状。目前关押弗洛雷…",
    "content": "新华社加拉加斯9月11日电（记者田睿）委内瑞拉执政党统一社会主义党11日在社交媒体发布公告说，遭美国关押的马杜罗总统夫妇的辩护团队以健康理由申请暂时释放第一夫人西莉亚·弗洛雷斯。 根据该公告，辩护团队向美国纽约一家法院提交了申请，请求基于“危急的医疗状况”、宪法原则及安全保证，批准第一夫人暂时获释。 公告显示，弗洛雷斯正经历“心脏及身体健康状况的严重恶化”，症状包括严重心律失常、心动过速以及符合冠状动脉缺血特征的发作症状。目前关押弗洛雷斯的布鲁克林大都会拘留中心“缺乏应对其健康状况所需的环境条件及临床医疗支持”。辩…"
