    "content": "新华社莫斯科9月11日电 俄联邦安全会议副主席、统一俄罗斯党主席梅德韦杰夫11日表示，俄罗斯没有任何针对欧洲的军事目标，欧洲领导层所谓“俄罗斯打算进攻欧洲”的说法，是为其援乌政策作辩护，以谋求在地缘政治上击败俄罗斯。 梅德韦杰夫当天在社交媒体发布的一段视频中说，欧洲各国目前民生承压，欧洲领导层编造“俄罗斯威胁论”，用以向民众解释为何要投入大量资金援助乌克兰。他说，炒作“俄罗斯威胁论”是为这场战争持续筹措资金的最佳手段。 梅德韦杰夫还说，俄罗斯国家领导层没有新一轮军事动员计划，因为完全没有必要，合同兵征召进度“已经达…"
