    "content": "新华社罗马9月11日电 联合国粮食及农业组织（粮农组织）渔业委员会第37届会议9月7日至11日在意大利首都罗马召开，中国代表团参加此次会议。 会议期间，中方和粮农组织共同主办“推动水产养殖创新，共促绿色可持续发展”边会，围绕技术创新、区域合作与发展、投资赋能与多方参与等开展讨论。新西兰、印度、南非、亚太水产养殖中心网（NACA）等国家和国际组织代表发言。中方在主旨报告中指出，2025年中国水产养殖产量6326万吨，占水产品总产量83%。中国坚持高质量水产养殖理念，实施水产种业振兴和养殖科技攻关，发展稻渔综合种养等新…"
