    "content": "一间特殊的“超市”，折射出中国市场的火爆。这间“超市”位于第二十六届中国国际投资贸易洽谈会现场，它不卖零食和饮料，而是将项目作为“产品”，以可视化“吊牌”形式分类上墙展示。到访这间“超市”的“顾客”扫码即可获取完整项目资料，项目方与投资方由此实现精准对接。记者看到，在投洽会短短的四天里，120余个项目厚厚的卡片迅速地变“薄”了，有的项目卡甚至“缺货”了。 在本届投洽会上，类似的场景还有很多。比如，ABB宣布升级其位于中国的智能制造基地；施耐德电气也持续加大在华创新投入，新工业园即将落成投产…… 在复杂的全球经济环境…"
