    "description": "新华社南昌9月11日电（记者陈浚武）由中宣部宣教局、光明日报社共同主办的“核心价值观百场讲坛”第172场活动9月11日在江西瑞金举办。此次活动以“中国共产党领导红军长征的光辉历程和伟大意义”为主题，中国人民大学中共党史党建研究院院长杨凤城作宣讲报告。 宣讲中，杨凤城回顾了红军在中国共产党领导下进行长征的伟大历程，结合血战湘江、遵义会议、四渡赤水、飞夺泸定桥、爬雪山过草地等重要事件和英雄壮举，解读了伟大长征精神的丰富内涵和时代价值，阐释了…",
    "content": "新华社南昌9月11日电（记者陈浚武）由中宣部宣教局、光明日报社共同主办的“核心价值观百场讲坛”第172场活动9月11日在江西瑞金举办。此次活动以“中国共产党领导红军长征的光辉历程和伟大意义”为主题，中国人民大学中共党史党建研究院院长杨凤城作宣讲报告。 宣讲中，杨凤城回顾了红军在中国共产党领导下进行长征的伟大历程，结合血战湘江、遵义会议、四渡赤水、飞夺泸定桥、爬雪山过草地等重要事件和英雄壮举，解读了伟大长征精神的丰富内涵和时代价值，阐释了中国共产党的领导是中国革命、建设、改革不断取得胜利最根本的保证。 杨凤城表示，伟…"
