    "description": "新华社纽约9月11日电（记者徐静）美国密歇根大学11日发布的初步调查数据显示，9月美国消费者信心指数初值为47.8，显著低于8月的51.7终值，连续第二个月下滑。 调查显示，9月当前经济状况指数初值为50.9，显著低于8月的51.9终值和去年同期的60.4；消费者预期指数初值为45.8，低于8月的51.5终值和去年同期的51.7。 同时，消费者对未来一年的通胀预期从8月的4.0%升至4.6%，长期通胀预期也小幅上升至3.4%。此前长期通…",
    "content": "新华社纽约9月11日电（记者徐静）美国密歇根大学11日发布的初步调查数据显示，9月美国消费者信心指数初值为47.8，显著低于8月的51.7终值，连续第二个月下滑。 调查显示，9月当前经济状况指数初值为50.9，显著低于8月的51.9终值和去年同期的60.4；消费者预期指数初值为45.8，低于8月的51.5终值和去年同期的51.7。 同时，消费者对未来一年的通胀预期从8月的4.0%升至4.6%，长期通胀预期也小幅上升至3.4%。此前长期通胀预期连续三个月维持在3.3%。 调查指出，民主、共和两党选民的消费信心指数均大…"
