    "content": "新华社上海9月11日电（记者陈潇雨、董雪）在9月11日举办的2026浦江创新论坛成果发布会上，上海市科学学研究所联合江苏省科技情报研究所、浙江省科技信息研究院、安徽省科技情报研究所发布《上海（长三角）国际科技创新中心建设智库观察报告》。报告显示，长三角区域创新协同持续深化，已基本形成“上海龙头引领、苏浙皖各扬所长、创新城市多点支撑、科创廊道协同联动”的一体化区域创新体系。 数据显示，以协同立法形式制定的科技创新法规《关于促进长三角科技创新协同发展的决定》2025年落地实施以来，5万余台套大型科学仪器实现跨区域共享，…"
