    "content": "新华社北京9月11日电（记者陈旭）记者11日从2026年服贸会人力资源服务业开放协作与融合发展大会上获悉，北京持续完善国际化人才评价与服务体系，建立并升级“京津冀国际职业资格证书查询验证服务平台”，截至今年8月，已累计为3600余家企业11000余人次提供证书查验服务及相关便利化服务保障，形成服务国际化专业人才来京创新创业的“北京模式”。 北京市人力资源和社会保障局副局长李李介绍，自2021年以来，北京市已连续5年系统推进国际职业资格认可改革工作，逐步实现境内外职业资格由“单边认可”向“双向互认”的重要跨越，被商务…"
