    "author": "刘振坤",
    "description": "一团黄胶泥，经揉捏、塑形，不一会儿就在指尖出现一只小鸟的造型；轻轻一吹，发出清脆的“咕咕”声，再经阴干、烧制、上色等多道工序，一个泥塑（浚县泥咕咕）便呈现在眼前。 近日，记者跟随“活力中国调研行”采访团，走进河南省鹤壁市浚县，探访国家级非物质文化遗产代表性项目泥塑（浚县泥咕咕）如何蜕变为带动乡村振兴的富民产业。 9月10日，在河南省浚县西杨玘屯村，村民从泥咕咕彩绘墙旁经过。新华社记者张帆 摄 走进浚县西杨玘屯村，首先映入眼帘的是“色彩”…",
    "content": "一团黄胶泥，经揉捏、塑形，不一会儿就在指尖出现一只小鸟的造型；轻轻一吹，发出清脆的“咕咕”声，再经阴干、烧制、上色等多道工序，一个泥塑（浚县泥咕咕）便呈现在眼前。 近日，记者跟随“活力中国调研行”采访团，走进河南省鹤壁市浚县，探访国家级非物质文化遗产代表性项目泥塑（浚县泥咕咕）如何蜕变为带动乡村振兴的富民产业。 9月10日，在河南省浚县西杨玘屯村，村民从泥咕咕彩绘墙旁经过。新华社记者张帆 摄 走进浚县西杨玘屯村，首先映入眼帘的是“色彩” —— 村道边的院墙上，黑底彩纹的泥咕咕绘画沿红墙铺展；工作坊内，形态各异、色彩…"
