    "content": "新华社北京9月11日电（记者周圆）算力网是人工智能发展的基础支撑。9月11日召开的国务院常务会议，研究算力网建设有关工作。 近年来，我国加快构建全国一体化算力网，形成以8大国家算力枢纽、10个国家算力集群、3个算电协同发展区域为重点的“8+10+3”算力空间布局，全国算力基础设施总量规模快速增长、算电协同深入推进、算网融合加速发展。 “要坚持合理布局、规范有序”“积极推进关键技术和装备研发应用”“构建多层次网络化算力体系”等，会议围绕算力基础设施建设作出一系列安排。 业内人士认为，当前算力网建设要突出统筹协同建设思…"
