    "description": "鹭岛九月，天蓝海碧，大厦之门迎四海宾客。 9月8日至11日，第二十六届中国国际投资贸易洽谈会在福建厦门举行，吸引了来自129个国家和地区、30个国际组织的1200多个政府官方机构、工商企业团组参会。 习近平总书记指出，中国国际投资贸易洽谈会以“扩大双向投资 共促全球发展”为永久主题，为推动建设开放型世界经济发挥了积极作用，已成为全球投资者深化务实合作的有效平台。 中国吸引外资和对外投资规模稳居世界前列，绿色低碳、智能制造、数字经济等领域…",
    "content": "鹭岛九月，天蓝海碧，大厦之门迎四海宾客。 9月8日至11日，第二十六届中国国际投资贸易洽谈会在福建厦门举行，吸引了来自129个国家和地区、30个国际组织的1200多个政府官方机构、工商企业团组参会。 习近平总书记指出，中国国际投资贸易洽谈会以“扩大双向投资 共促全球发展”为永久主题，为推动建设开放型世界经济发挥了积极作用，已成为全球投资者深化务实合作的有效平台。 中国吸引外资和对外投资规模稳居世界前列，绿色低碳、智能制造、数字经济等领域成为双向投资热门赛道，双向投资政策体系持续完善……记者在本届投洽会上感受到，中国…"
