    "content": "9月11日，在斯里兰卡首都科伦坡，斯里兰卡大众媒体部副部长考沙利娅·阿里亚拉特内在“2026中斯媒体合作交流”研讨会上致辞。新华社记者 李俞辉 摄 新华社科伦坡9月11日电（记者李俞辉 刘天）以“信任与共赢——中斯命运共同体背景下的媒体担当”为主题的“2026中斯媒体合作交流”研讨会11日在斯里兰卡首都科伦坡举行。来自中斯两国政府部门、媒体、智库、高校等领域的80余名嘉宾出席会议，围绕构建中斯命运共同体、深化中斯战略合作伙伴关系、深化媒体交流合作与中斯民心相通等议题展开深入研讨。 斯里兰卡大众媒体部副部长考沙利娅·…"
