    "author": "吴琼",
    "description": "新华社仰光9月11日电（记者吴琼）缅甸曼德勒国际机场运行指挥中心11日表示，该机场内的航班现已恢复正常，旅客可在机场搭乘航班。 缅甸丹伦航空当晚在社交媒体上说，原计划备降彬乌伦近郊机场的航班将恢复正常，在曼德勒国际机场降落。 缅甸官媒《缅甸环球新光报》11日报道说，10日下午，有“恐怖分子”使用6架无人机对曼德勒国际机场及周边区域发动袭击。安全部队拦截了无人机，并对无人机携带的爆炸物进行无害化处理。袭击未造成人员伤亡，车辆及跑道也未受损…",
    "content": "新华社仰光9月11日电（记者吴琼）缅甸曼德勒国际机场运行指挥中心11日表示，该机场内的航班现已恢复正常，旅客可在机场搭乘航班。 缅甸丹伦航空当晚在社交媒体上说，原计划备降彬乌伦近郊机场的航班将恢复正常，在曼德勒国际机场降落。 缅甸官媒《缅甸环球新光报》11日报道说，10日下午，有“恐怖分子”使用6架无人机对曼德勒国际机场及周边区域发动袭击。安全部队拦截了无人机，并对无人机携带的爆炸物进行无害化处理。袭击未造成人员伤亡，车辆及跑道也未受损。机场部分航班暂时停飞。 据报道，缅甸官方谴责这一袭击事件，称其构成战争罪。安全…"
