    "content": "金砖是当今世界最重要的新兴市场和发展中国家团结合作平台。自成立以来，金砖国家秉持开放包容、合作共赢的金砖精神，致力于捍卫多边主义、维护公平正义、谋求共同发展，已经成为名副其实的全球南方第一方阵。 从最初的4个成员国到如今的“大金砖”格局，金砖国家合作机制成为全球南方国家凝聚共识、协同发展的核心平台，为更多发展中国家提供了融入全球经济治理、提升国际话语权的契机。 作为金砖合作中坚力量、全球南方核心成员，中国在“大金砖合作”中发挥了重要的推动和引领作用。如今，“大金砖合作”已经迈入高质量发展阶段。 编导：惠培培、洪凌、…"
