    "description": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 作为金砖合作的倡导者和推动者，习近平主席多次以“船”为喻，为金砖国家携手前行指引方向，推动金砖大船行稳致远。 策划：钱彤 石锋 统筹：黄庆华 王浩程 编导/制作：唐颢宸 新华社新媒体中心制作 新华社出品",
