    "title": "中国证监会严肃查处*ST卓然严重财务造假案件",
    "link": "http://www.news.cn/20260911/aa088936836f4903b04e13d6a228c5fa/c.html",
    "pub_date": "2026-09-11 23:29:48",
    "author": "刘慧",
    "description": "新华社北京9月11日电（记者刘慧、刘羽佳）中国证监会9月11日宣布，近日对上市公司上海卓然工程技术股份有限公司（*ST卓然）涉嫌定期报告等财务数据存在虚假记载作出行政处罚事先告知。 证监会信息显示，经查，*ST卓然相关年度存在虚增利润等行为，严重违反证券法律法规。证监会拟对上市公司罚款1250万元，对6名责任人合计罚款3580万元，对实际控制人采取10年证券市场禁入。*ST卓然涉嫌触及重大违法强制退市情形，上交所将依法启动退市程序。 证…",
    "content": "新华社北京9月11日电（记者刘慧、刘羽佳）中国证监会9月11日宣布，近日对上市公司上海卓然工程技术股份有限公司（*ST卓然）涉嫌定期报告等财务数据存在虚假记载作出行政处罚事先告知。 证监会信息显示，经查，*ST卓然相关年度存在虚增利润等行为，严重违反证券法律法规。证监会拟对上市公司罚款1250万元，对6名责任人合计罚款3580万元，对实际控制人采取10年证券市场禁入。*ST卓然涉嫌触及重大违法强制退市情形，上交所将依法启动退市程序。 证监会表示，决定对本案所涉会计师事务所执业行为正式立案调查，涉嫌未能勤勉尽责的将依…"
