    "content": "新华社纽约9月11日电（记者刘亚南）美国劳工部11日发布的数据显示，受燃油价格走高等因素推动，8月消费者价格指数（CPI）环比上涨0.4%，同比涨幅保持在3.4%不变。 数据显示，美国8月CPI环比涨幅从7月的0.1%显著升高至0.4%。美国8月汽油价格环比上涨3.9%，对当月CPI涨幅的贡献超三分之一。食品和能源价格8月分别环比上涨0.1%和2.1%。 数据还显示，扣除食品和能源，美国8月核心CPI环比上涨0.3%，而7月涨幅和市场预期均为0.2%。核心CPI同比涨幅则从7月的2.5%回落至2.4%，符合市场预期…"
