    "content": "9月11日，在菲律宾巴拉望省，救援人员在事故现场工作。新华社发（菲律宾海警供图） 新华社马尼拉9月11日电（记者赵晨捷 李萌）菲律宾媒体11日援引菲海岸警卫队消息报道说，救援人员当天在巴拉望省附近海域的一艘起火客船上发现30具遗体。该事故目前已造成35人遇难，尚有54人失联。 据菲媒最新报道，这艘载有132人的客轮从首都马尼拉出发后，9日在科伦镇附近海域起火。菲媒称目前有43人幸存。菲海警发布的视频画面显示，客轮已被严重烧毁，现场可见灰烬和烧焦的金属。 菲律宾群岛民众的日常出行依赖渡轮。受极端天气、船舶维护不善、超…"
