    "description": "新华社马普托9月11日电（记者刘杰）莫桑比克总统查波10日在该国伊尼扬巴内省出席由中企承建的莫桑比克基西科高等理工学院揭幕仪式。他表示，该学院的建成将为当地渔业发展和青年就业发挥更大作用。 查波在致辞中说，该学院将有助于提升水产品生产和加工能力，帮助青年提升就业创业能力，为当地创造更多发展机会。 基西科高等理工学院位于伊尼扬巴内省萨瓦拉区基西科镇，开设水产养殖工程、水产品加工与质量控制工程等专业。 该学院院长塞尔吉奥·穆莱马表示，中企建…",
    "content": "新华社马普托9月11日电（记者刘杰）莫桑比克总统查波10日在该国伊尼扬巴内省出席由中企承建的莫桑比克基西科高等理工学院揭幕仪式。他表示，该学院的建成将为当地渔业发展和青年就业发挥更大作用。 查波在致辞中说，该学院将有助于提升水产品生产和加工能力，帮助青年提升就业创业能力，为当地创造更多发展机会。 基西科高等理工学院位于伊尼扬巴内省萨瓦拉区基西科镇，开设水产养殖工程、水产品加工与质量控制工程等专业。 该学院院长塞尔吉奥·穆莱马表示，中企建设的校园基础设施现代、实用，能够满足教学和实验实践需要，也为当地青年接受高等教育…"
