    "content": "新华社深圳9月11日电（记者孙飞）记者11日从深圳市市场监管局相关负责人处获悉，深圳市融资信用服务平台（地方征信平台）自2022年1月正式运营以来，持续深化信用数据开发应用、服务中小微企业融资，到今年8月末，平台累计服务企业融资突破10000亿元，融资金额达10316.33亿元，累计服务企业超97万家，其中首贷户企业超13万家，平台金融基础设施服务效能持续释放。 深圳市融资信用服务平台相关负责人介绍，作为深圳市唯一融合应用政务数据和商业数据的平台，平台已融合地方及全国企业数据超99亿条，涵盖企业工商、司法、税务、海…"
