    "description": "新华社加沙/耶路撒冷9月11日电（记者赵伟宏 冯国芮）巴勒斯坦伊斯兰抵抗运动（哈马斯）下属武装派别卡桑旅11日发表声明说，卡桑旅总军事委员会成员兼汗尤尼斯旅高级指挥官穆罕默德·亚祖里10日在以色列“暗杀行动”中身亡。 声明说，亚祖里曾在哈马斯2023年10月对以色列发起的“阿克萨洪水”行动中发挥重要作用。 以色列国防军当天早些时候发表声明称，以军与国家安全总局（辛贝特）10日在汗尤尼斯地区实施打击行动，打死了亚祖里。",
    "content": "新华社加沙/耶路撒冷9月11日电（记者赵伟宏 冯国芮）巴勒斯坦伊斯兰抵抗运动（哈马斯）下属武装派别卡桑旅11日发表声明说，卡桑旅总军事委员会成员兼汗尤尼斯旅高级指挥官穆罕默德·亚祖里10日在以色列“暗杀行动”中身亡。 声明说，亚祖里曾在哈马斯2023年10月对以色列发起的“阿克萨洪水”行动中发挥重要作用。 以色列国防军当天早些时候发表声明称，以军与国家安全总局（辛贝特）10日在汗尤尼斯地区实施打击行动，打死了亚祖里。"
