    "description": "新华社北京9月11日电 题：烧伤烫伤后，第一时间该怎么做 新华社记者李志浩、黄凯莹、田子骏 9月12日是“世界急救日”。热水、热油、蒸汽、明火、高温物体……生活中，烧伤烫伤并不少见。意外发生后，有人急着涂烫伤膏，有人拿牙膏、酱油等“土办法”救急，还有人直接冰敷、挑破水疱……这些习以为常的做法，可能潜藏误区，延误病情。 烧伤烫伤后，第一时间该怎么做？ “临床上最常见的烫伤烧伤是热液烫伤，比如开水、热粥、热油、热汤等，此外还有火焰烧伤。”广…",
    "content": "新华社北京9月11日电 题：烧伤烫伤后，第一时间该怎么做 新华社记者李志浩、黄凯莹、田子骏 9月12日是“世界急救日”。热水、热油、蒸汽、明火、高温物体……生活中，烧伤烫伤并不少见。意外发生后，有人急着涂烫伤膏，有人拿牙膏、酱油等“土办法”救急，还有人直接冰敷、挑破水疱……这些习以为常的做法，可能潜藏误区，延误病情。 烧伤烫伤后，第一时间该怎么做？ “临床上最常见的烫伤烧伤是热液烫伤，比如开水、热粥、热油、热汤等，此外还有火焰烧伤。”广西医科大学第一附属医院皮肤性病科副主任医师张馨予说，在临床上，烫伤和烧伤的急救和…"
