    "content": "公信力冲击慈善捐赠，防止公益滥用是政府规制的应有目的。回顾近年慈善监管运行历程，虽强化了流程规范，但难以从根源上遏制公益滥用。要打破困局需探寻规范与活力之间的平衡，守护善心，促进慈善良性发展。 文/贾西津 责任编辑：钟金秀 9月“中华慈善日”，“久久公益节”，对于不少公益组织而言可能是一年中最重要的筹款季。不过近两年的数据显示，2024年公益慈善组织接收慈善捐赠总额比上一年下降12.30%，2025年基金会年度总量第一次出现负增长。 经济增速放缓是对公益捐赠的一个影响因素，但居民人均可支配收入仍然一直是增长趋势，在…"
