    "description": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 经各方共同努力，金砖合作机制已成为当今世界最重要的新兴市场国家和发展中国家团结合作平台。作为这一机制的坚定支持者和参与者，中国始终秉持开放包容、合作共赢的金砖精神，积极贡献中国智慧与方案，同金砖伙伴在发展振兴的道路上携手同行。 当前，世界百年变局加速演进，霸权主义、单边主义、保护主义甚嚣尘上。只要我们担当作为、守望相助，金砖这艘大…",
    "content": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 经各方共同努力，金砖合作机制已成为当今世界最重要的新兴市场国家和发展中国家团结合作平台。作为这一机制的坚定支持者和参与者，中国始终秉持开放包容、合作共赢的金砖精神，积极贡献中国智慧与方案，同金砖伙伴在发展振兴的道路上携手同行。 当前，世界百年变局加速演进，霸权主义、单边主义、保护主义甚嚣尘上。只要我们担当作为、守望相助，金砖这艘大船就一定能够经受住国际风云变幻的考验，始终行稳致远。 习近平主席此次出席金砖国家…"
