    "pub_date": "2026-09-11 22:04:22",
    "author": "",
    "description": "中新网江西庐山9月11日电 (朱莹 刘力鑫 吴思瑜)9月11日晚，赣台荟·第三届赣台青年短视频创作大赛颁奖仪式在江西庐山举行。作为第二十届赣台(庐山)经贸文化合作交流大会的重要专题活动之一，本次颁奖仪式吸引了700余名两岸同胞齐聚现场，共赏两岸青年影像佳作，共叙赣台同根深情。",
    "content": "中新网江西庐山9月11日电 (朱莹 刘力鑫 吴思瑜)9月11日晚，赣台荟·第三届赣台青年短视频创作大赛颁奖仪式在江西庐山举行。作为第二十届赣台(庐山)经贸文化合作交流大会的重要专题活动之一，本次颁奖仪式吸引了700余名两岸同胞齐聚现场，共赏两岸青年影像佳作，共叙赣台同根深情。"
