    "title": "活力中国调研行丨泥咕咕“唱出”新旋律 非遗赋能和美乡村",
    "link": "http://www.news.cn/20260911/40cb881af4444971a73f71102a1ba33d/c.html",
    "pub_date": "2026-09-11 21:53:17",
    "author": "杨静,沙世源",
    "description": "一捧黄胶泥，经指尖揉捏塑形，转瞬便化作昂首翘尾的灵动小鸟；轻吹之下，清脆的“咕咕”声响起，再经阴干、烧制、上色等多道传统工序，传承千年的国家级非物质文化遗产代表性项目泥塑（浚县泥咕咕）便焕然成型。近日，记者跟随“活力中国调研行”采访团走进河南鹤壁浚县，探访这项传承了上千年的技艺如何蜕变为带动乡村振兴的富民产业。 据了解，西杨玘屯村现有泥咕咕展示馆、传习所、博物馆、大师工坊等文化场馆36处，工匠艺人1000多名，年销售泥塑作品2000多万…",
    "content": "一捧黄胶泥，经指尖揉捏塑形，转瞬便化作昂首翘尾的灵动小鸟；轻吹之下，清脆的“咕咕”声响起，再经阴干、烧制、上色等多道传统工序，传承千年的国家级非物质文化遗产代表性项目泥塑（浚县泥咕咕）便焕然成型。近日，记者跟随“活力中国调研行”采访团走进河南鹤壁浚县，探访这项传承了上千年的技艺如何蜕变为带动乡村振兴的富民产业。 据了解，西杨玘屯村现有泥咕咕展示馆、传习所、博物馆、大师工坊等文化场馆36处，工匠艺人1000多名，年销售泥塑作品2000多万件，年产值达到4800多万元。 记者：沙世源 杨静 新华社音视频部制作"
