    "description": "9月10日，在法国巴黎中国文化中心，一名男子在中国古代饮食文化展上参观。新华社记者 邬惠我 摄 新华社巴黎9月11日电（记者张百慧 孙毅）由法国巴黎中国文化中心与中国国家博物馆联合举办的“宴飨万年——数说中国古代饮食文化”展览10日在巴黎中国文化中心开幕。 展览展出30余件（组）古代饮食器具仿制品，设置“庖厨之道”“琳琅美器”“侑宴之艺”“宴会雅集”四个单元，从食材、器具、技艺、礼仪、审美等角度展现中国古代饮食文化的演变。从新石器时代用…",
    "content": "9月10日，在法国巴黎中国文化中心，一名男子在中国古代饮食文化展上参观。新华社记者 邬惠我 摄 新华社巴黎9月11日电（记者张百慧 孙毅）由法国巴黎中国文化中心与中国国家博物馆联合举办的“宴飨万年——数说中国古代饮食文化”展览10日在巴黎中国文化中心开幕。 展览展出30余件（组）古代饮食器具仿制品，设置“庖厨之道”“琳琅美器”“侑宴之艺”“宴会雅集”四个单元，从食材、器具、技艺、礼仪、审美等角度展现中国古代饮食文化的演变。从新石器时代用于炊煮的陶鼎、汉代青铜染炉，到清代紫铜火锅，不同时期、材质和用途的器具仿制品反映…"
