    "title": "货值超1.7亿 广东销毁83吨侵权假冒伪劣商品",
    "link": "http://www.news.cn/20260911/a8b2561d746b470f92efc5e71f5d788d/c.html",
    "pub_date": "2026-09-11 21:38:29",
    "author": "胡林果",
    "description": "9月10日，2026年侵权假冒伪劣商品全国统一销毁行动举行。广东分会场设在清远市，此次分会场销毁活动集中了清远市各行政执法部门查获的各类侵权假冒伪劣商品，涵盖食品、化妆品、箱包、鞋类等主要品类，共计29.7万余件，重量约83.2吨，货值约1.75亿元。2025年，广东全省市场监管系统共查办假冒伪劣案件15656宗，罚没1.32亿元，移送公安机关212宗，有力打击了侵权假冒违法行为。 作者：胡林果、李庆招 新华社音视频部制作",
