    "description": "聚焦“戏曲文献收藏研究与活化利用”主题，第八期“文瀚雅集”活动近日在中国国家版本馆中央总馆举办。 来自各地的收藏家带来并展出了明清以来戏曲文献版本120余件，其中不乏清桐华阁刊本《第六才子书：西厢记》、民国版本《元曲别裁集》《牡丹亭曲谱》、抗战胜利后梅兰芳首次复出商演的戏单及剧本等珍贵戏曲史料。 清桐华阁刊本《第六才子书：西厢记》。（国家版本馆供图） 座谈交流中，20余位收藏家、专家学者、艺术家和出版界人士围绕戏曲文献存藏现状、征集收藏…",
    "content": "聚焦“戏曲文献收藏研究与活化利用”主题，第八期“文瀚雅集”活动近日在中国国家版本馆中央总馆举办。 来自各地的收藏家带来并展出了明清以来戏曲文献版本120余件，其中不乏清桐华阁刊本《第六才子书：西厢记》、民国版本《元曲别裁集》《牡丹亭曲谱》、抗战胜利后梅兰芳首次复出商演的戏单及剧本等珍贵戏曲史料。 清桐华阁刊本《第六才子书：西厢记》。（国家版本馆供图） 座谈交流中，20余位收藏家、专家学者、艺术家和出版界人士围绕戏曲文献存藏现状、征集收藏保护体系构建、价值发掘，戏曲文献数字化、活态戏曲艺术传承等议题进行了深入探讨。 …"
