    "content": "新华社北京9月11日电（记者戴小河）国家市场监督管理总局11日通报，我国深入推动地方标准管理制度改革，组织31个省份全面开展地方标准清理，截至6月底已废止地方标准7400余项。 这是市场监管总局当日召开的“破除妨碍统一市场和公平竞争卡点堵点专项行动”专题新闻发布会公布的信息。 今年5月至12月，市场监管总局组织开展破除妨碍统一市场和公平竞争卡点堵点专项行动，旨在营造更加公平、更有活力的市场环境。市场监管总局竞争协调司副司长赵春雷介绍，目前，专项行动取得了三方面阶段性成效： 第一，清除隐性壁垒，商品要素流动更加顺畅。…"
