    "description": "8月11日，巴西夫妇在厦门大学附属心血管病医院研修学习。新华社发 新华社厦门9月11日电 题：金砖合作架起跨国医疗“连心桥” 新华社记者付敏 今年4月，来自巴西东北部萨尔瓦多市的埃里克·梅尔卡多与阿曼达·梅尔卡多夫妇抵达厦门，在厦门大学附属心血管病医院（以下简称“厦心医院”）开启为期六个月的微创心脏诊疗技术专项进修。 微创心脏手术在中国已是临床常规诊疗手段，该技术创伤小、恢复快、诊疗精度高，但这项技术目前尚未在巴西医疗体系普及，是巴西心…",
    "content": "8月11日，巴西夫妇在厦门大学附属心血管病医院研修学习。新华社发 新华社厦门9月11日电 题：金砖合作架起跨国医疗“连心桥” 新华社记者付敏 今年4月，来自巴西东北部萨尔瓦多市的埃里克·梅尔卡多与阿曼达·梅尔卡多夫妇抵达厦门，在厦门大学附属心血管病医院（以下简称“厦心医院”）开启为期六个月的微创心脏诊疗技术专项进修。 微创心脏手术在中国已是临床常规诊疗手段，该技术创伤小、恢复快、诊疗精度高，但这项技术目前尚未在巴西医疗体系普及，是巴西心脏诊疗领域的技术短板。 数月的临床学习与观摩，彻底更新了梅尔卡多夫妇对心脏疾病精…"
