    "content": "新华社香港9月11日电 “TopGBR全球医疗健康与生命科学品牌排行榜”11日在香港启动，旨在构建客观中立的评估体系，协助相关企业塑造国际品牌形象并拓展全球市场。 该排行榜由全球品牌研究院（GBR）发起、香港城市大学提供学术支持，当天在香港会展中心举行的“第五届香港国际生物科技论坛暨展览(BIOHK2026)”现场举行启幕推介及启动仪式。 在仪式上，BIOHK大会主席于常海、中国医药创新促进会副会长冯岚、全球品牌研究院执行理事彭伟东等携手为榜单启幕赋能。据主办方介绍，该排行榜立足香港国际创科枢纽优势，聚焦全球创新药…"
