    "description": "据知情人士透露，预测市场平台 Kalshi 计划申请监管批准，推出美国首批受监管的个股永续期货，挂钩标的包括特斯拉、苹果与英伟达。这类被称作永续合约（perps）的产品允许交易者全天候交易，还可叠加杠杆，放大潜在收益与亏损；无到期日的特性进一步放大了风险。（新浪财经）",
    "content": "据知情人士透露，预测市场平台 Kalshi 计划申请监管批准，推出美国首批受监管的个股永续期货，挂钩标的包括特斯拉、苹果与英伟达。这类被称作永续合约（perps）的产品允许交易者全天候交易，还可叠加杠杆，放大潜在收益与亏损；无到期日的特性进一步放大了风险。（新浪财经）"
