    "content": "中新社江西庐山9月11日电 (朱莹 刘占昆 刘力鑫)海峡两岸关系协会会长张志军11日在江西庐山表示，尽管当前外部形势变乱交织、严峻复杂，但大陆经济航船顶压前行、向优向好，持续保持经济快速发展和社会长期稳定，祖国大陆仍是广大台商台胞发展的最优选择。"
